// test-large-libraries-decimal.js
const jsdom = require('jsdom');
const {JSDOM} = jsdom;
const DOM = require('lighthouse-core/report/html/renderer/dom.js');
const Util = require('lighthouse-core/report/html/renderer/util.js');
const I18n = require('lighthouse-core/report/html/renderer/i18n.js');
const DetailsRenderer = require('lighthouse-core/report/html/renderer/details-renderer.js');

// 1) Create a minimal DOM + renderer
const {document} = new JSDOM(`<!DOCTYPE html><html><body></body></html>`).window;
const dom = new DOM(document);
// Attach I18n to Util (required by the renderer)
Util.i18n = new I18n('en', {...Util.UIStrings});
const renderer = new DetailsRenderer(dom);
renderer.setTemplateContext(document);

// 2) Build a “table” details object for Large JS libraries
const details = {
  type: 'table',
  headings: [
    {key: 'name', itemType: 'text', text: 'Library'},
    {key: 'transferSize', itemType: 'bytes', text: 'Transfer Size'},
  ],
  items: [
    {name: 'date-fns', transferSize: 18 * 1024},            // exactly 18.0 KiB
    {name: 'luxon',   transferSize: Math.round(20.4 * 1024)}, // 20.4 KiB
  ],
};

// 3) Render and inspect the formatted cells
const table = renderer.render(details);
const rows = table.querySelectorAll('tbody tr');
for (const row of rows) {
  const nameCell = row.querySelector('td.lh-table-column--text');
  const sizeCell = row.querySelector('td.lh-table-column--bytes');
  console.log(nameCell.textContent.trim(), sizeCell.textContent.trim());
}

// Expected console output under current code:
// date-fns 18 KiB    ← missing ".0"
// luxon   20.4 KiB
